using Rhino;using Rhino.DocObjects;
namespace RhinoContextAssist;
internal sealed class ContextAssistController:IDisposable{readonly ContextAssistSettings settings;readonly HudState state=new();readonly ContextAssistHudConduit conduit;readonly ContextAssistMouseCallback mouse;CommandSearchWindow? search;internal ContextAssistController(ContextAssistSettings s){settings=s;conduit=new(state,s){Enabled=true};mouse=new(state,s,Run,OpenSearch);}internal void Start(){RhinoDoc.SelectObjects+=Changed;RhinoDoc.DeselectObjects+=Changed;RhinoDoc.DeselectAllObjects+=Cleared;RhinoDoc.CloseDocument+=Closed;Refresh();}void Changed(object?s,RhinoObjectSelectionEventArgs e)=>Refresh();void Cleared(object?s,RhinoDeselectAllObjectsEventArgs e)=>Clear();void Closed(object?s,DocumentEventArgs e)=>Clear();internal void Refresh(){var d=RhinoDoc.ActiveDoc;if(d==null||!settings.Enabled){Clear();return;}state.Context=SelectionAnalyzer.Analyze(d);state.Actions.Clear();state.Actions.AddRange(settings.Sort(ActionCatalog.Get(state.Context)));state.ViewSerial=d.Views.ActiveView?.RuntimeSerialNumber??0;state.HoverIndex=-1;d.Views.Redraw();}void Run(ContextAction a){settings.Used(a.Id);RhinoApp.RunScript(a.Macro,false);search?.Close();search=null;}void OpenSearch(){if(search is{IsVisible:true}){search.Activate();return;}search=new CommandSearchWindow(state.Actions,Run);search.Closed+=(_,_)=>search=null;search.Show();}void Clear(){state.Actions.Clear();RhinoDoc.ActiveDoc?.Views.Redraw();}public void Dispose(){RhinoDoc.SelectObjects-=Changed;RhinoDoc.DeselectObjects-=Changed;RhinoDoc.DeselectAllObjects-=Cleared;RhinoDoc.CloseDocument-=Closed;mouse.Enabled=false;conduit.Enabled=false;search?.Close();}}
